// exportDialog.js - the Export sheet: choose files, format, mode and pages; see a REAL preview of what will be
// written; download. The preview and the download are the same generated bytes, so they cannot differ.
// Generation is cancellable between steps (a single library call such as the final PDF save cannot be interrupted).
import { el, icon } from '../dom.js';
import { FORMATS, unsupportedReason, exportOne, zipResults, tableChoices, defaultCsvTable, buildPasteText } from '../../export/index.js';
import { createPageSource, paint } from '../editor/pageSource.js';
import { tablesOf, buildExportData } from '../../export/data.js';
import { createPreview } from '../editor/preview.js';
import { formatBytes } from '../../format.js';

const MODE_LABEL = { original: 'Original appearance (page images)', structured: 'Structured (editable text and tables)' };
const MODE_HELP = {
  original: 'Faithful archival pages exactly as scanned, in your page order and rotation. Not editable.',
  structured: 'Rebuilt from your corrected values. Real text and tables; it does not copy the original layout.',
};

export function createExportDialog({ workspace, store, session, engines, toaster, srLive }) {
  let ids = [];
  let selected = new Set();
  let state = { pagesFor: null, format: 'pdf', mode: 'structured', pages: new Set(), includeNotes: true, includeText: true, textLayer: true, csvTable: null, stem: '' };
  let result = null; // last generated {blob, filename, ...}
  let ctrl = null;
  let timer = null;
  let opener = null;
  let runId = 0;

  const dlg = el('dialog', { class: 'exp', 'aria-labelledby': 'exp-title' });
  const title = el('h2', { id: 'exp-title', class: 'exp-title' }, 'Export');
  const closeBtn = el('button', { type: 'button', class: 'icon-btn', 'aria-label': 'Close export' }, icon('x'));
  const left = el('div', { class: 'exp-controls' });
  const right = el('div', { class: 'exp-preview-col' });
  const status = el('p', { class: 'exp-status', role: 'status', 'aria-live': 'polite' });
  const err = el('p', { class: 'exp-error', role: 'alert' });
  const warn = el('ul', { class: 'exp-warn' });
  const meter = el('div', { class: 'meter exp-meter', role: 'progressbar', 'aria-label': 'Export progress', 'aria-valuemin': '0', 'aria-valuemax': '100', 'aria-valuenow': '0', hidden: true }, el('span'));
  const cancelBtn = el('button', { type: 'button', class: 'btn btn-secondary' }, 'Cancel');
  const copyBtn = el('button', { type: 'button', class: 'btn btn-secondary' }, 'Copy for pasting');
  const dlBtn = el('button', { type: 'button', class: 'btn btn-primary' }, icon('download', 'icon-sm'), 'Download');
  const foot = el('div', { class: 'exp-foot' }, el('div', { class: 'exp-foot-msg' }, status, err, meter), el('div', { class: 'exp-actions' }, cancelBtn, copyBtn, dlBtn));
  dlg.append(el('div', { class: 'exp-head' }, title, closeBtn), el('div', { class: 'exp-body' }, left, right), warn, foot);
  document.body.append(dlg);

  // ------------------------------------------------------------------ helpers
  const ready = () => store.getState().items.filter((i) => workspace.ensure(i.id));
  const entryOf = (id) => workspace.ensure(id);
  const single = () => (selected.size === 1 ? entryOf([...selected][0]) : null);
  const dataProbe = () => { const e = entryOf([...selected][0] ?? ids[0]); return e; };

  function pageSourceOf(e) {
    e.pageSource ??= createPageSource({ item: e.item, result: e.result, engines });
    return e.pageSource;
  }
  const renderFor = (e) => async (source, rotation) => {
    const base = await pageSourceOf(e).render(source, 3_000_000);
    const c = document.createElement('canvas');
    paint(c, base, rotation);
    return c;
  };

  function radio(group, value, label, { checked, disabled, help, onChange }) {
    const id = `exp-${group}-${value}`;
    const input = el('input', { type: 'radio', name: `exp-${group}`, id, value, checked, disabled });
    input.addEventListener('change', () => onChange(value));
    return el('div', { class: `opt${disabled ? ' is-disabled' : ''}` }, input, el('label', { for: id }, label), help ? el('p', { class: 'opt-help', id: `${id}-h` }, help) : null);
  }
  function check(id, label, checked, onChange, { disabled = false, help } = {}) {
    const input = el('input', { type: 'checkbox', id, checked, disabled });
    input.addEventListener('change', () => onChange(input.checked));
    return el('div', { class: 'opt' }, input, el('label', { for: id }, label), help ? el('p', { class: 'opt-help' }, help) : null);
  }

  // ------------------------------------------------------------------ controls
  function renderControls() {
    const e1 = single();
    if (e1 && state.pagesFor !== e1.id) { state.pages = new Set(e1.doc.pages.map((p) => p.source)); state.pagesFor = e1.id; }
    const parts = [];

    // files
    const fileBox = el('fieldset', { class: 'exp-set' }, el('legend', {}, 'Files'));
    const files = ready();
    ids = files.map((i) => i.id);
    for (const it of files) {
      const id = `exp-file-${it.id}`;
      const input = el('input', { type: 'checkbox', id, checked: selected.has(it.id) });
      input.addEventListener('change', () => { if (input.checked) selected.add(it.id); else selected.delete(it.id); onChange(true); });
      fileBox.append(el('div', { class: 'opt' }, input, el('label', { for: id }, it.name)));
    }
    if (!files.length) fileBox.append(el('p', { class: 'opt-help' }, 'No recognized files yet.'));
    if (files.length > 1) fileBox.append(el('p', { class: 'opt-help' }, selected.size > 1 ? 'Several files are bundled into one ZIP, one export per file.' : 'Select more files to bundle them into one ZIP.'));
    parts.push(fileBox);

    // format
    const fmt = el('fieldset', { class: 'exp-set' }, el('legend', {}, 'Format'));
    for (const [k, f] of Object.entries(FORMATS)) {
      fmt.append(radio('format', k, k === 'csv' ? 'Google Sheets (CSV)' : f.label, { checked: state.format === k, onChange: (v) => { state.format = v; if (!FORMATS[v].modes.includes(state.mode)) state.mode = 'structured'; onChange(true); } }));
    }
    parts.push(fmt);

    // mode
    const mode = el('fieldset', { class: 'exp-set' }, el('legend', {}, 'What to export'));
    for (const m of ['original', 'structured']) {
      const why = unsupportedReason(state.format, m);
      mode.append(radio('mode', m, MODE_LABEL[m], { checked: state.mode === m && !why, disabled: !!why, help: why ?? MODE_HELP[m], onChange: (v) => { state.mode = v; onChange(true); } }));
    }
    parts.push(mode);

    // pages (one file only)
    if (e1) {
      const pg = el('fieldset', { class: 'exp-set' }, el('legend', {}, 'Pages'));
      e1.doc.pages.forEach((p, i) => pg.append(check(`exp-page-${p.source}`, `Page ${i + 1}${p.rotation ? ` (rotated ${p.rotation}°)` : ''}`, state.pages.has(p.source), (c) => { if (c) state.pages.add(p.source); else state.pages.delete(p.source); onChange(true); })));
      parts.push(pg);
    }

    // options
    const opt = el('fieldset', { class: 'exp-set' }, el('legend', {}, 'Options'));
    const orig = state.format === 'pdf' && state.mode === 'original';
    opt.append(check('exp-notes', 'Include review notes (checks still open)', state.includeNotes, (c) => { state.includeNotes = c; onChange(true); }, { disabled: orig }));
    opt.append(check('exp-text', 'Include recognized page text', state.includeText, (c) => { state.includeText = c; onChange(true); }, { disabled: orig }));
    if (orig) opt.append(check('exp-layer', 'Searchable text layer (as recognized, not your edits)', state.textLayer, (c) => { state.textLayer = c; onChange(true); }));
    const probe = e1 ?? dataProbe();
    if (state.format === 'csv' && probe) {
      const choices = tableChoices(buildProbeData(probe));
      const sel = el('select', { id: 'exp-table', class: 'select' }, ...choices.map((c) => el('option', { value: c.id }, c.name)));
      if (!choices.some((c) => c.id === state.csvTable)) state.csvTable = defaultCsvTable(buildProbeData(probe));
      sel.value = state.csvTable ?? '';
      sel.addEventListener('change', () => { state.csvTable = sel.value; onChange(true); });
      opt.append(el('div', { class: 'opt opt-select' }, el('label', { for: 'exp-table' }, 'Table'), sel, el('p', { class: 'opt-help' }, 'A CSV holds one table. Google Sheets opens it with File > Import, or paste with "Copy for pasting". No Google account access is used.')));
    }
    const nameId = 'exp-name';
    const nameIn = el('input', { id: nameId, class: 'input', type: 'text', value: state.stem, placeholder: 'File name (without extension)', autocomplete: 'off', maxlength: '80' });
    nameIn.addEventListener('input', () => { state.stem = nameIn.value; schedule(); });
    opt.append(el('div', { class: 'opt opt-select' }, el('label', { for: nameId }, 'File name'), nameIn));
    parts.push(opt);

    left.replaceChildren(...parts);
    copyBtn.hidden = state.format !== 'csv' || selected.size !== 1;
  }

  const buildProbeData = (entry) => buildExportData(entry.doc, { result: entry.result });

  // ------------------------------------------------------------------ generation
  function onChange(rerenderControls) {
    if (rerenderControls) { const f = document.activeElement?.id; renderControls(); if (f) document.getElementById(f)?.focus(); }
    schedule();
  }
  function schedule() {
    clearTimeout(timer);
    cancelRun();
    result = null;
    err.textContent = '';
    setBusy(true, 'Preparing…');
    timer = setTimeout(generate, 250);
  }
  function cancelRun() { ctrl?.abort(); ctrl = null; }

  function setBusy(busy, text = '') {
    dlBtn.disabled = busy || !result;
    copyBtn.disabled = busy || !result;
    cancelBtn.textContent = busy ? 'Cancel' : 'Close';
    status.textContent = text;
    meter.hidden = !busy || state.mode !== 'original' || state.format !== 'pdf';
    dlg.setAttribute('aria-busy', String(busy));
  }
  function setProgress(done, total) {
    const v = total ? Math.round((done / total) * 100) : 0;
    meter.firstElementChild.style.width = `${v}%`;
    meter.setAttribute('aria-valuenow', String(v));
    status.textContent = `Rendering page ${Math.min(done + 1, total)} of ${total}…`;
  }

  async function generate() {
    const my = (runId += 1);
    err.textContent = '';
    warn.replaceChildren();
    const sel = ids.filter((i) => selected.has(i));
    if (!sel.length) { setBusy(false, ''); err.textContent = 'Select at least one file.'; preview.replaceChildren(); return; }
    ctrl = new AbortController();
    const { signal } = ctrl;
    try {
      const results = [];
      for (let n = 0; n < sel.length; n += 1) {
        const e = entryOf(sel[n]);
        const one = sel.length === 1;
        if (!one) { status.textContent = `Building ${n + 1} of ${sel.length}: ${e.doc.name}…`; }
        const r = await exportOne({
          entry: e, format: state.format, mode: state.mode, pages: one ? [...state.pages] : null, includeNotes: state.includeNotes, includeText: state.includeText,
          textLayer: state.textLayer, csvTable: state.csvTable, stem: one ? state.stem : '', renderPage: renderFor(e), signal,
          onProgress: one ? setProgress : undefined,
        });
        if (signal.aborted || my !== runId) return;
        results.push(r);
      }
      let out = results[0];
      if (results.length > 1) out = { ...(await zipResults(results)), warnings: results.flatMap((r) => r.warnings), data: results[0].data, multi: results };
      if (signal.aborted || my !== runId) return;
      result = out;
      setBusy(false, `Ready: ${out.filename} (${formatBytes(out.blob.size)})`);
      dlBtn.disabled = false; copyBtn.disabled = false;
      warn.replaceChildren(...[...new Set(out.warnings)].map((w) => el('li', {}, icon('info', 'icon-sm'), w)));
      await showPreview(results[0], results.length);
    } catch (e) {
      if (e?.name === 'AbortError' || signal.aborted || my !== runId) return;
      result = null;
      setBusy(false, '');
      err.textContent = `Export failed: ${e.message || 'unknown error'}`;
      preview.replaceChildren();
    }
  }

  // ------------------------------------------------------------------ preview (of the generated output)
  const preview = el('div', { class: 'exp-preview', 'aria-label': 'Preview', role: 'region', tabindex: '0' });
  right.append(el('h3', { class: 'exp-h3' }, 'Preview'), preview);
  let pvRun = 0;
  async function showPreview(first, count) {
    const my = (pvRun += 1);
    const note = count > 1 ? el('p', { class: 'opt-help' }, `Showing the first of ${count} files.`) : null;
    if (state.format === 'pdf') {
      const canvas = el('canvas', { class: 'exp-pv-canvas', role: 'img', 'aria-label': 'First page of the generated PDF' });
      const info = el('p', { class: 'opt-help' }, '');
      preview.replaceChildren(...[note, el('p', { class: 'opt-help' }, 'Rendered from the generated PDF itself.'), info, canvas].filter(Boolean));
      try {
        const doc = await engines.pdf.open(new Uint8Array(await first.blob.arrayBuffer()));
        try {
          const page = await doc.renderPage(0, { rotation: 0, maxPixels: 1_400_000 });
          if (my !== pvRun) return;
          canvas.width = page.width; canvas.height = page.height;
          canvas.getContext('2d').drawImage(page, 0, 0);
          info.textContent = `${doc.numPages} ${doc.numPages === 1 ? 'page' : 'pages'}, ${formatBytes(first.blob.size)}.`;
        } finally { await doc.destroy?.(); }
      } catch { if (my === pvRun) info.textContent = 'Preview could not be rendered, but the file was generated.'; }
      return;
    }
    if (state.format === 'docx') {
      const pv = createPreview();
      pv.update({ doc: first.doc });
      preview.replaceChildren(...[note, el('p', { class: 'opt-help' }, 'Content preview: the Word file is built from exactly these values (a Word layout is not rendered in the browser).'), pv.node].filter(Boolean));
      return;
    }
    // xlsx / csv: the cell grid that is written
    const tables = tablesOf(first.data).filter((t) => state.format !== 'csv' || t.name === first.table);
    preview.replaceChildren(...[note, el('p', { class: 'opt-help' }, state.format === 'xlsx' ? 'Cells that will be written. Amounts are numbers, not text.' : 'The rows of this CSV file.'),
      ...tables.map((t) => el('div', { class: 'pv-sheet' }, el('h4', { class: 'ed-h3' }, state.format === 'xlsx' ? `Sheet: ${t.name}` : t.name),
        el('div', { class: 'tbl-wrap' }, el('table', { class: 'pv-table' }, el('tbody', {}, ...t.rows.slice(0, 40).map((r, ri) => el('tr', {}, ...r.map((c) => el(t.header && ri === 0 ? 'th' : 'td', { scope: t.header && ri === 0 ? 'col' : null }, c === null ? '' : String(c)))))))),
        t.rows.length > 40 ? el('p', { class: 'opt-help' }, `…and ${t.rows.length - 40} more rows.`) : null))].filter(Boolean));
  }

  // ------------------------------------------------------------------ download / copy / close
  function download() {
    if (!result) return;
    const url = URL.createObjectURL(result.blob);
    const a = el('a', { href: url, download: result.filename });
    document.body.append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 30_000);
    const msg = `Downloaded ${result.filename} (${formatBytes(result.blob.size)}).`;
    status.textContent = msg;
    srLive(msg);
    toaster.show(msg, 'success');
  }
  async function copy() {
    const e = single();
    if (!e) return;
    const text = buildPasteText(buildProbeData(e), state.csvTable);
    try {
      await navigator.clipboard.writeText(text);
      status.textContent = 'Copied. Paste into Google Sheets (Ctrl+V).';
    } catch {
      const ta = el('textarea', { class: 'visually-hidden', 'aria-hidden': 'true' }, text);
      document.body.append(ta); ta.select();
      const ok = document.execCommand?.('copy'); ta.remove();
      status.textContent = ok ? 'Copied. Paste into Google Sheets (Ctrl+V).' : '';
      if (!ok) err.textContent = 'Your browser blocked copying. Use Download instead.';
    }
    srLive(status.textContent);
  }
  function close() {
    cancelRun(); clearTimeout(timer); runId += 1; pvRun += 1;
    result = null;
    if (dlg.open) dlg.close();
    preview.replaceChildren();
    opener?.focus?.();
  }

  closeBtn.addEventListener('click', close);
  cancelBtn.addEventListener('click', () => { if (cancelBtn.textContent === 'Cancel' && ctrl) { cancelRun(); runId += 1; setBusy(false, 'Cancelled.'); result = null; dlBtn.disabled = true; } else close(); });
  dlBtn.addEventListener('click', download);
  copyBtn.addEventListener('click', copy);
  dlg.addEventListener('cancel', (e) => { e.preventDefault(); close(); }); // Esc
  dlg.addEventListener('click', (e) => { if (e.target === dlg) close(); }); // backdrop

  return {
    /** @param {string[]|null} preselect file ids to tick; null = all recognized files */
    open(preselect = null, from = null) {
      opener = from ?? document.activeElement;
      const files = ready();
      ids = files.map((i) => i.id);
      selected = new Set(preselect ? preselect.filter((i) => ids.includes(i)) : ids);
      const e1 = selected.size === 1 ? entryOf([...selected][0]) : null;
      state = { ...state, pages: new Set(e1 ? e1.doc.pages.map((p) => p.source) : []), pagesFor: e1?.id ?? null, stem: '', csvTable: null };
      if (!FORMATS[state.format].modes.includes(state.mode)) state.mode = 'structured';
      title.textContent = 'Export';
      renderControls();
      if (!dlg.open) dlg.showModal();
      schedule();
      closeBtn.focus();
    },
    close,
    get isOpen() { return dlg.open; },
  };
}
